src = rep(src, "function fitArena(keep){ const aw=arena.clientWidth, ah=arena.clientHeight; if(!aw||!ah) return; Z.aw=aw; Z.ah=ah; if(aw/ah>Z.aspect){ Z.H=ah; Z.W=Math.round(ah*Z.aspect); } else { Z.W=aw; Z.H=Math.round(aw/Z.aspect); }", "function fbH(){ return parseFloat(getComputedStyle(arena).getPropertyValue('--fb'))||30; }\n/* 가로폰: HUD·진행점이 아레나 위에 겹치므로 그만큼 위를 비워 보드 상단 타깃이 가려지지 않게 */\nfunction topH(){ const h=document.querySelector('#play .hud'); if(!h||getComputedStyle(h).position!=='absolute') return 0; const a=arena.getBoundingClientRect(); let b=h.getBoundingClientRect().bottom; const p=$('prog'); if(p&&getComputedStyle(p).position==='absolute') b=Math.max(b,p.getBoundingClientRect().bottom); return Math.max(0, Math.round(b-a.top)+2); }\nfunction fitArena(keep){ const aw=arena.clientWidth, ah0=arena.clientHeight; if(!aw||!ah0) return; const ah=ah0-fbH()-topH(); Z.aw=aw; Z.ah=ah0; if(aw/ah>Z.aspect){ Z.H=ah; Z.W=Math.round(ah*Z.aspect); } else { Z.W=aw; Z.H=Math.round(aw/Z.aspect); }")
src = rep(src, "function clampZ(){ const sw=Z.W*Z.s, sh=Z.H*Z.s; Z.tx = sw<=Z.aw ? (Z.aw-sw)/2 : Math.min(0,Math.max(Z.aw-sw,Z.tx)); Z.ty = sh<=Z.ah ? (Z.ah-sh)/2 : Math.min(0,Math.max(Z.ah-sh,Z.ty)); }", "function clampZ(){ const sw=Z.W*Z.s, sh=Z.H*Z.s, fb=fbH()+topH(); Z.tx = sw<=Z.aw ? (Z.aw-sw)/2 : Math.min(0,Math.max(Z.aw-sw,Z.tx)); Z.ty = sh<=Z.ah-fb ? fb+(Z.ah-fb-sh)/2 : Math.min(fb,Math.max(Z.ah-sh,Z.ty)); }")
src = rep(src, "function applyZ(){ layer.style.transform=`translate(${Z.tx}px,${Z.ty}px) scale(${Z.s})`;", "function applyZ(){ layer.style.transform=`translate(${Z.tx}px,${Z.ty}px) scale(${Z.s})`; const fr=$('frame'); fr.style.transform=`translate(${Z.tx}px,${Z.ty-fbH()}px)`; fr.style.width=Math.max(120,Z.W*Z.s)+'px';")
src = rep(src, "function centerZ(){ Z.tx=(Z.aw-Z.W*Z.s)/2; Z.ty=(Z.ah-Z.H*Z.s)/2; clampZ(); applyZ(); }", "function centerZ(){ const fb=fbH()+topH(); Z.tx=(Z.aw-Z.W*Z.s)/2; Z.ty=fb+(Z.ah-fb-Z.H*Z.s)/2; clampZ(); applyZ(); }")
